import{_ as o,o as a,c as t,ae as i}from"./chunks/framework.C4zpkcTP.js";const h=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"configuration.md","filePath":"configuration.md"}'),n={name:"configuration.md"};function d(l,e,r,c,s,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>DockPilot is configured through environment variables. The relevant files are <code>.env.example</code> at the repository root and <code>apps/api/.env.example</code>.</p><h2 id="core-variables" tabindex="-1">Core variables <a class="header-anchor" href="#core-variables" aria-label="Permalink to &quot;Core variables&quot;">​</a></h2><ul><li><code>NODE_ENV</code> — <code>development</code>, <code>test</code>, or <code>production</code>.</li><li><code>DATABASE_URL</code> — PostgreSQL connection string.</li><li><code>SESSION_SECRET</code> — unique, high-entropy session key.</li><li><code>MCP_ENABLED</code> — set to <code>false</code> to serve no MCP endpoint at all.</li><li><code>MCP_TOKEN_SECRET</code> — independent HMAC key for AI credential tokens.</li><li><code>HOST</code>, <code>API_PORT</code>, <code>WEB_PORT</code>, <code>WEB_ORIGIN</code>, <code>API_PUBLIC_URL</code>, <code>TRUSTED_PROXY</code> — network and origin settings.</li></ul><h2 id="secrets" tabindex="-1">Secrets <a class="header-anchor" href="#secrets" aria-label="Permalink to &quot;Secrets&quot;">​</a></h2><p>Production requires a unique, cryptographically generated <code>SESSION_SECRET</code> and, when MCP is enabled, an independent <code>MCP_TOKEN_SECRET</code>. The startup validation rejects placeholder values.</p><p>To generate a suitable secret:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;console.log(require(&#39;node:crypto&#39;).randomBytes(48).toString(&#39;base64url&#39;))&quot;</span></span></code></pre></div><p>Use two separately generated values for <code>SESSION_SECRET</code> and <code>MCP_TOKEN_SECRET</code>.</p><h2 id="local-development-defaults" tabindex="-1">Local development defaults <a class="header-anchor" href="#local-development-defaults" aria-label="Permalink to &quot;Local development defaults&quot;">​</a></h2><p>For local development, the Compose PostgreSQL service listens only on <code>127.0.0.1:54329</code>. Web and API dev servers default to loopback origins. The example <code>.env</code> values are deliberately rejected at startup until you replace the secrets.</p><h2 id="mcp-control" tabindex="-1">MCP control <a class="header-anchor" href="#mcp-control" aria-label="Permalink to &quot;MCP control&quot;">​</a></h2><ul><li>Set <code>MCP_ENABLED=false</code> to serve no MCP endpoint at all.</li><li>When MCP is enabled, production requires <code>MCP_TOKEN_SECRET</code>.</li><li>Outside production, <code>MCP_TOKEN_SECRET</code> falls back to a value derived from <code>SESSION_SECRET</code>.</li><li>The stdio entry point is for local development only and authenticates from <code>DOCKPILOT_MCP_TOKEN</code>.</li></ul>',13)])])}const _=o(n,[["render",d]]);export{h as __pageData,_ as default};
